  if o.paint==false then q.color=nil end
  if o.mirrorX then q.x=-q.x;q.ry=-(q.ry or 0);q.rz=-(q.rz or 0) end
  if o.mirrorZ then q.z=-q.z;q.rx=-(q.rx or 0);q.ry=-(q.ry or 0) end
  out[#out+1]=q
 end
